    /// Reserved keyword the lexer emits for `text`.
    pub fn hard_keyword(text: &str) -> Option<SyntaxKind> {
        Some(match text {
            "package" => PACKAGE_KEYWORD,
            "as" => AS_KEYWORD,
            "typealias" => TYPE_ALIAS_KEYWORD,
            "class" => CLASS_KEYWORD,
            "this" => THIS_KEYWORD,
            "super" => SUPER_KEYWORD,
            "val" => VAL_KEYWORD,
            "var" => VAR_KEYWORD,
            "fun" => FUN_KEYWORD,
            "for" => FOR_KEYWORD,
            "null" => NULL_KEYWORD,
            "true" => TRUE_KEYWORD,
            "false" => FALSE_KEYWORD,
            "is" => IS_KEYWORD,
            "in" => IN_KEYWORD,
            "throw" => THROW_KEYWORD,
            "return" => RETURN_KEYWORD,
            "break" => BREAK_KEYWORD,
            "continue" => CONTINUE_KEYWORD,
            "object" => OBJECT_KEYWORD,
            "if" => IF_KEYWORD,
            "try" => TRY_KEYWORD,
            "else" => ELSE_KEYWORD,
            "while" => WHILE_KEYWORD,
            "do" => DO_KEYWORD,
            "when" => WHEN_KEYWORD,
            "interface" => INTERFACE_KEYWORD,
            "typeof" => TYPEOF_KEYWORD,
            "as?" => AS_SAFE,
            "!in" => NOT_IN,
            "!is" => NOT_IS,
            _ => return None,
        })
    }

    /// Soft or modifier keyword for `text`; lexed as IDENTIFIER, remapped by the parser.
    pub fn soft_keyword(text: &str) -> Option<SyntaxKind> {
        Some(match text {
            "all" => ALL_KEYWORD,
            "file" => FILE_KEYWORD,
            "field" => FIELD_KEYWORD,
            "property" => PROPERTY_KEYWORD,
            "receiver" => RECEIVER_KEYWORD,
            "param" => PARAM_KEYWORD,
            "setparam" => SETPARAM_KEYWORD,
            "delegate" => DELEGATE_KEYWORD,
            "import" => IMPORT_KEYWORD,
            "where" => WHERE_KEYWORD,
            "by" => BY_KEYWORD,
            "get" => GET_KEYWORD,
            "set" => SET_KEYWORD,
            "constructor" => CONSTRUCTOR_KEYWORD,
            "init" => INIT_KEYWORD,
            "context" => CONTEXT_KEYWORD,
            "abstract" => ABSTRACT_KEYWORD,
            "enum" => ENUM_KEYWORD,
            "contract" => CONTRACT_KEYWORD,
            "open" => OPEN_KEYWORD,
            "inner" => INNER_KEYWORD,
            "override" => OVERRIDE_KEYWORD,
            "private" => PRIVATE_KEYWORD,
            "public" => PUBLIC_KEYWORD,
            "internal" => INTERNAL_KEYWORD,
            "protected" => PROTECTED_KEYWORD,
            "catch" => CATCH_KEYWORD,
            "out" => OUT_KEYWORD,
            "vararg" => VARARG_KEYWORD,
            "reified" => REIFIED_KEYWORD,
            "dynamic" => DYNAMIC_KEYWORD,
            "companion" => COMPANION_KEYWORD,
            "sealed" => SEALED_KEYWORD,
            "finally" => FINALLY_KEYWORD,
            "final" => FINAL_KEYWORD,
            "lateinit" => LATEINIT_KEYWORD,
            "data" => DATA_KEYWORD,
            "value" => VALUE_KEYWORD,
            "inline" => INLINE_KEYWORD,
            "noinline" => NOINLINE_KEYWORD,
            "tailrec" => TAILREC_KEYWORD,
            "external" => EXTERNAL_KEYWORD,
            "annotation" => ANNOTATION_KEYWORD,
            "crossinline" => CROSSINLINE_KEYWORD,
            "operator" => OPERATOR_KEYWORD,
            "infix" => INFIX_KEYWORD,
            "const" => CONST_KEYWORD,
            "suspend" => SUSPEND_KEYWORD,
            "expect" => EXPECT_KEYWORD,
            "actual" => ACTUAL_KEYWORD,
            _ => return None,
        })
    }

